// Public SSG HTML only. Dynamic profiles, jobs, auth and ISR stay behind the
// renderer. No bulk profile data is generated by this build step.
import { readFileSync, writeFileSync, mkdirSync, existsSync, copyFileSync } from 'node:fs';
import { resolve, relative, join } from 'node:path';
import { createHash } from 'node:crypto';

const prerender = JSON.parse(readFileSync('.next/prerender-manifest.json', 'utf8'));
const routes = JSON.parse(readFileSync('.next/routes-manifest.json', 'utf8'));
const buildId = readFileSync('.next/BUILD_ID', 'utf8').trim();
const root = resolve('.next/server/app');
const destination = `.open-next/assets/cdn-cgi/cvin-static/${buildId}`;
mkdirSync(destination, { recursive: true });
const manifest = Object.create(null);
for (const [path, route] of Object.entries(prerender.routes)) {
  if (route.initialRevalidateSeconds !== false || (route.initialStatus && route.initialStatus !== 200)) continue;
  if (/^\/(?:_|admin|editor|preview|signup|login|auth)(?:\/|$)/.test(path) || path.startsWith('/_')) continue;
  if (!route.dataRoute?.endsWith('.rsc')) continue;
  const input = resolve(root, route.dataRoute.replace(/^\//, '').replace(/\.rsc$/, '.html'));
  if (relative(root, input).startsWith('..') || !existsSync(input)) continue;
  const filename = `${createHash('sha256').update(path).digest('hex').slice(0, 20)}.html-body`;
  copyFileSync(input, join(destination, filename));
  const headers = {};
  for (const rule of routes.headers || []) {
    if (new RegExp(rule.regex).test(path)) {
      for (const header of rule.headers) {
        if (!/^(set-cookie|content-length)$/i.test(header.key)) headers[header.key] = header.value;
      }
    }
  }
  manifest[path] = { asset: `/cdn-cgi/cvin-static/${buildId}/${filename}`, headers };
}
writeFileSync('.open-next/static-pages.json', JSON.stringify(manifest));
console.log(`Prepared ${Object.keys(manifest).length} public static HTML routes for the lightweight gateway`);
